```js
const roles = ['web apps.', 'design systems.', 'fast APIs.'];
const el = document.getElementById('typed');
let ri = 0, ci = 0, deleting = false;
(function tick() {
  const word = roles[ri];
  el.textContent = word.slice(0, ci);
  if (!deleting && ci < word.length) ci++;
  else if (deleting && ci > 0) ci--;
  else if (!deleting) { deleting = true; return setTimeout(tick, 1400); }
  else { deleting = false; ri = (ri + 1) % roles.length; }
  setTimeout(tick, deleting ? 40 : 90);
})();
const top = document.getElementById('top');
addEventListener('scroll', () => { top.hidden = scrollY < 400; }, { passive: true });
top.addEventListener('click', () => scrollTo({ top: 0, behavior: 'smooth' }));
```

Why it works: the typing loop is a single recursive setTimeout that types, pauses, deletes and moves to the next word, and the back-to-top button uses the passive scroll listener so it never blocks scrolling.

