**js/app.js**
```js
let cart = [
  { id: 1, name: 'Canvas Sneaker', price: 79, qty: 1 },
  { id: 2, name: 'Wool Beanie', price: 24, qty: 2 }
];
const items = document.getElementById('items');
const totalEl = document.getElementById('total');

function render() {
  items.innerHTML = cart.map(i => `
    <div class='item' data-id='${i.id}'>
      <h3>${i.name}</h3>
      <div class='qty'>
        <button data-act='minus' aria-label='Decrease'>-</button>
        <span>${i.qty}</span>
        <button data-act='plus' aria-label='Increase'>+</button>
      </div>
      <span>$${(i.price * i.qty).toFixed(2)}</span>
      <button class='remove' data-act='remove'>Remove</button>
    </div>`).join('');
  const total = cart.reduce((s, i) => s + i.price * i.qty, 0);
  totalEl.textContent = '$' + total.toFixed(2);
}

items.addEventListener('click', e => {
  const btn = e.target.closest('button');
  if (!btn) return;
  const id = Number(btn.closest('.item').dataset.id);
  const line = cart.find(i => i.id === id);
  if (btn.dataset.act === 'plus') line.qty++;
  if (btn.dataset.act === 'minus') line.qty = Math.max(1, line.qty - 1);
  if (btn.dataset.act === 'remove') cart = cart.filter(i => i.id !== id);
  render();
});
render();
```

Why it works: one delegated click listener handles every button through data-act attributes, state lives in a single array, and render() is the only function that touches the DOM — so the total can never drift out of sync.

