const tabs = [...document.querySelectorAll('[role=tab]')];
const panels = [...document.querySelectorAll('[role=tabpanel]')];

function activate(tab) {
  tabs.forEach(t => {
    const on = t === tab;
    t.setAttribute('aria-selected', on);
    document.getElementById(t.getAttribute('aria-controls')).hidden = !on;
  });
  tab.focus();
}

tabs.forEach(tab => {
  tab.addEventListener('click', () => activate(tab));
  tab.addEventListener('keydown', e => {
    const i = tabs.indexOf(tab);
    if (e.key === 'ArrowRight') activate(tabs[(i + 1) % tabs.length]);
    if (e.key === 'ArrowLeft') activate(tabs[(i - 1 + tabs.length) % tabs.length]);
  });
});
```

Why it works: the ARIA wiring (tablist/tab/tabpanel, aria-selected, aria-controls) is what screen readers rely on to announce 'Tab 2 of 3, selected'. Hidden panels are removed with the hidden attribute rather than CSS, so they cannot leak through a stylesheet change. Arrow-key navigation with wrap-around follows the WAI-ARIA tabs pattern, and activate() is a single source of truth that both clicks and keyboard events call, so the two input paths can never disagree.

